#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

bool isPrime(int k) {
    if (k <= 1) return false;
    if (k <= 3) return true;
    if (k % 2 == 0 || k % 3 == 0) return false;
    for (int i = 5; 1LL * i * i <= k; i += 6) {
        if (k % i == 0 || k % (i + 2) == 0) return false;
    }
    return true;
}

long long modpow(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int x;
    long long n;
    cin >> x >> n;

    vector<int> primes;
    for (int i = 2; 1LL * i * i <= x; ++i) {
        if (x % i == 0) {
            if (isPrime(i)) primes.push_back(i);
            int other = x / i;
            if (other != i && isPrime(other)) primes.push_back(other);
        }
    }
    if (isPrime(x)) primes.push_back(x);

    long long ans = 1;
    for (int p : primes) {
        long long curP = p;
        while (curP <= n) {
            ans = (ans * modpow(p, n / curP)) % MOD;
            if (curP > n / p) break;
            curP *= p;
        }
    }

    cout << ans << "\n";
    return 0;
}

