#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

const int64 MOD = 1000000007;

bool isPrime(int k) {
    if (k <= 1) return false;
    if (k <= 3) return true;
    if (k % 2 == 0 || k % 3 == 0) return false;
    for (int i = 5; i * 1LL * i <= k; i += 6) {
        if (k % i == 0 || k % (i + 2) == 0) return false;
    }
    return true;
}

int64 power(int64 x, int64 p) {
    int64 res = 1;
    x %= MOD;
    while (p > 0) {
        if (p & 1) res = (res * x) % MOD;
        x = (x * x) % MOD;
        p >>= 1;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int x;
    int64 n;
    cin >> x >> n;

    vector<int> primes;
    int temp_x = x;
    for (int i = 2; i * 1LL * i <= temp_x; ++i) {
        if (temp_x % i == 0) {
            primes.push_back(i);
            while (temp_x % i == 0) temp_x /= i;
        }
    }
    if (temp_x > 1) primes.push_back(temp_x);

    int64 ans = 1;
    for (int p : primes) {
        int64 curP = p;
        while (curP <= n) {
            ans = (ans * power(p, n / curP)) % MOD;
            if (curP > n / p) break;
            curP *= p;
        }
    }

    cout << ans << "\n";
    return 0;
}

