        while (n / curP > 0) {
            //println(curP)
            ans = (ans * power(p.toLong(), n / curP)) % mod
            if ((curP * p) / p != curP) break
            curP *= p
        }
    }

    println(ans)
}

class Scanner(s: InputStream) {
    var st: StringTokenizer? = null
    val br: BufferedReader = BufferedReader(InputStreamReader(s))

    operator fun next(): String {
        while (st == null || !st!!.hasMoreTokens())
            st = StringTokenizer(br.readLine())
        return st!!.nextToken()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }

    fun nextLine(): String {
        return br.readLine()
    }

    fun nextDouble(): Double {
        return java.lang.Double.parseDouble(next())
    }

    companion object {
        val sysIn = Scanner(System.`in`)
    }

}

val rnd = Random()
fun IntArray.sort() {
    val n = this.size
    for (i in 0 until n - 1) {
        val randomPos = i + rnd.nextInt(n - i - 1) + 1
        this[i] = this[i] xor this[randomPos]
        this[randomPos] = this[randomPos] xor this[i]
        this[i] = this[i] xor this[randomPos]
    }
    Arrays.sort(this)
}

fun LongArray.sort() {
    val n = this.size
    for (i in 0 until n - 1) {
        val randomPos = i + rnd.nextInt(n - i - 1) + 1
        this[i] = this[i] xor this[randomPos]
        this[randomPos] = this[randomPos] xor this[i]
        this[i] = this[i] xor this[randomPos]
    }
    Arrays.sort(this)
}
